<?php require "config/db.php"; require_login(); $cart=$_SESSION["cart"]??[];if(!$cart){header("Location: menu.php");exit;} $items=[];$total=0;foreach($cart as $id=>$qty){$s=$pdo->prepare("SELECT * FROM foods WHERE id=? AND is_available=1");$s->execute([$id]);if($f=$s->fetch()){$f["qty"]=$qty;$total+=(float)$f["price"]*$qty;$items[]=$f;}}$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){ $phone=trim($_POST["phone"]??"");$address=trim($_POST["address"]??"");if(!preg_match('/^[0-9+\-\s]{8,20}$/',$phone)||strlen($address)<10){$error="Enter a valid phone number and delivery address (at least 10 characters).";}else{try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO orders(user_id,customer_name,phone,address,total) VALUES(?,?,?,?,?)");$s->execute([$_SESSION["user"]["id"],$_SESSION["user"]["name"],$phone,$address,$total]);$oid=$pdo->lastInsertId();$si=$pdo->prepare("INSERT INTO order_items(order_id,food_id,food_name,quantity,unit_price) VALUES(?,?,?,?,?)");foreach($items as $it)$si->execute([$oid,$it["id"],$it["name"],$it["qty"],$it["price"]]);$pdo->commit();unset($_SESSION["cart"]);header("Location: my_orders.php?placed=1");exit;}catch(Exception $e){$pdo->rollBack();$error="Could not place your order. Please try again.";}}} ?>
